// ---- firm/lib/text.js ----
// Small text helpers shared by intake, triage and booking. Pure functions, no I/O.
// Files in firm/lib are bundled into n8n Code nodes by scripts/build-intake-workflow.mjs,
// so every top-level name in these files must be unique across the folder.

function lowerText(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .replace(/['‘’]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const PHRASE_REGEX_CACHE = {};
function phraseRegex(phrase) {
  if (!PHRASE_REGEX_CACHE[phrase]) {
    const words = lowerText(phrase).replace(/[^a-z0-9]+/g, ' ').trim().split(' ');
    // Whole words only. A phrase may be followed by a plural or past-tense ending (divorce, divorced).
    PHRASE_REGEX_CACHE[phrase] = new RegExp('(^|[^a-z0-9])(' + words.join('[^a-z0-9]+') + ')(?:s|es|ed|d)?(?![a-z0-9])', 'g');
  }
  return PHRASE_REGEX_CACHE[phrase];
}

// First match of a phrase in already-lowercased text, or null. Indexes refer to the text as given.
function findPhrase(text, phrase) {
  const re = phraseRegex(phrase);
  re.lastIndex = 0;
  const m = re.exec(text);
  if (!m) return null;
  const index = m.index + m[1].length;
  return { index, end: index + m[2].length };
}

// Replace a span with spaces so later searches cannot match inside it and indexes stay stable.
function maskSpan(text, start, end) {
  return text.slice(0, start) + ' '.repeat(end - start) + text.slice(end);
}

// Phrases that would otherwise hit the wrong practice area ('real estate' is not estate planning,
// 'in custody' is not child custody).
function stripAmbiguousPhrases(text) {
  return text.replace(/\breal estate\b/g, ' ').replace(/\b(?:in|police|county|jail) custody\b/g, ' ');
}

// Phrases that would otherwise look like court dates or served papers.
// Same length as the input, so indexes still point into the original text.
function stripHarmlessPhrases(text) {
  const blank = (m) => ' '.repeat(m.length);
  return text
    .replace(/\bhard of hearing\b/g, blank)
    .replace(/\bhearing (?:aids?|loss|impaired|impairment|problems?)\b/g, blank)
    // 'I keep hearing that...', 'I have not been hearing from my lawyer': the verb, not a court hearing
    .replace(/\b(?:keep|keeps|kept|been|always|often|just|am|was|were) hearing\b/g, blank)
    .replace(/\bhearing (?:that|about|from|different|conflicting|things|rumou?rs|stories|voices)\b/g, blank)
    .replace(/\bserved (?:in|as|my country|with the (?:army|navy|air force|marines))\b/g, blank);
}

// ---- firm/lib/areas.js ----
// Match a message to the firm's practice areas. Input: what the person selected and what they wrote.
// data is firm/practice-areas.json. Returns the area, how sure we are (basis) and which keywords hit.
// This never gives legal advice: it only decides where a message should go.

function classifyArea(input, data) {
  const selected = (input && input.selected) || 'not_sure';
  const ids = data.areas.map((a) => a.id);
  const hits = {};
  ids.forEach((id) => { hits[id] = []; });
  const outHits = {};
  data.outOfScope.forEach((o) => { outHits[o.id] = []; });

  // Longest phrases first, across both lists, and mask each match, so that
  // 'guardianship of a child' (family) is not also counted as 'guardianship' (estate).
  const all = [];
  data.areas.forEach((a) => a.keywords.forEach((k) => all.push({ k, kind: 'area', id: a.id })));
  data.outOfScope.forEach((o) => o.keywords.forEach((k) => all.push({ k, kind: 'out', id: o.id })));
  all.sort((x, y) => y.k.length - x.k.length);
  let work = stripAmbiguousPhrases(lowerText(input && input.text));
  for (const e of all) {
    let m = findPhrase(work, e.k);
    if (!m) continue;
    (e.kind === 'area' ? hits[e.id] : outHits[e.id]).push(e.k);
    while (m) {
      work = maskSpan(work, m.index, m.end);
      m = findPhrase(work, e.k);
    }
  }

  const count = {};
  ids.forEach((id) => { count[id] = hits[id].length; });
  const order = ids.slice().sort((a, b) => count[b] - count[a] || ids.indexOf(a) - ids.indexOf(b));
  const top = order[0];
  const topCount = count[top];
  const tied = ids.filter((id) => count[id] === topCount && topCount > 0);
  const withHits = ids.filter((id) => count[id] > 0);
  const outRanked = data.outOfScope
    .map((o) => ({ o, n: outHits[o.id].length }))
    .filter((x) => x.n > 0)
    .sort((a, b) => b.n - a.n);
  const outTop = outRanked.length ? outRanked[0].o : null;

  let area;
  let basis;
  let also = [];
  if (topCount === 0 && outTop) {
    area = 'out_of_scope';
    basis = 'inferred';
  } else if (ids.includes(selected)) {
    const others = order.filter((id) => id !== selected);
    const bestOther = others[0];
    const bestOtherCount = count[bestOther];
    if (count[selected] >= 1 && count[selected] >= bestOtherCount) {
      area = selected; basis = 'selected'; also = withHits.filter((id) => id !== selected);
    } else if (count[selected] >= 1) {
      area = selected; basis = 'mixed'; also = withHits.filter((id) => id !== selected);
    } else if (bestOtherCount >= 2) {
      area = bestOther; basis = 'differs'; also = withHits.filter((id) => id !== bestOther);
    } else {
      area = selected; basis = 'selected_unsupported'; also = withHits;
    }
  } else if (topCount === 0) {
    area = 'unclear'; basis = 'unclear';
  } else if (tied.length === 1) {
    area = top; basis = 'inferred'; also = withHits.filter((id) => id !== top);
  } else {
    area = top; basis = 'mixed'; also = tied.filter((id) => id !== top);
  }

  const shown = {};
  ids.forEach((id) => { if (hits[id].length) shown[id] = hits[id]; });
  return {
    area,
    basis,
    hits: shown,
    alsoMentions: also,
    outOfScope: area === 'out_of_scope' && outTop ? { id: outTop.id, name: outTop.name, referral: outTop.referral } : null,
    alsoOutOfScope: area === 'out_of_scope' ? [] : outRanked.map((x) => x.o.id)
  };
}

// ---- firm/lib/conflicts.js ----
// Conflict check against the firm's invented conflict list (firm/conflicts.json).
// A match never decides anything. It holds the lead so an attorney can clear it, and the person
// is never told why. The check does not model relatives, subsidiaries or aliases; a real firm's
// practice-management system does. See automations/intake/README.md for the limits.

function normalizeName(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\b(inc|llc|ltd|co|corp|company|llp)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// 'A and B', 'A, B', 'A vs B' become separate names. The whole string is checked as well.
function splitNames(s) {
  const whole = normalizeName(s);
  if (!whole) return [];
  const parts = String(s)
    .split(/\s*(?:,|;|\n|&|\/|\band\b|\bvs\.?\s|\bv\.\s)\s*/i)
    .map(normalizeName)
    .filter((x) => x.length >= 2);
  return Array.from(new Set([whole].concat(parts)));
}

function containsPhrase(haystack, needle) {
  return (' ' + haystack + ' ').indexOf(' ' + needle + ' ') !== -1;
}

// True when two words differ by at most one inserted, deleted or changed letter.
function withinOneEdit(a, b) {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1) return false;
  let i = 0;
  while (i < a.length && i < b.length && a.charAt(i) === b.charAt(i)) i++;
  if (a.length === b.length) return a.slice(i + 1) === b.slice(i + 1);
  return a.length > b.length ? a.slice(i + 1) === b.slice(i) : a.slice(i) === b.slice(i + 1);
}

// Returns 'match', 'near match', 'ambiguous' or null for one normalized name against one entry.
function compareName(q, entry) {
  const e = normalizeName(entry.name);
  if (!q || !e) return null;
  if (q === e) return 'match';
  const qt = q.split(' ');
  const et = e.split(' ');
  if (entry.type === 'person' && qt.length >= 2 && et.length >= 2 && qt[0].charAt(0) === et[0].charAt(0)) {
    const ql = qt[qt.length - 1];
    const el = et[et.length - 1];
    // Same first initial and the same last name, allowing one typo in a longer last name (Kesler, Kessler).
    if (ql === el || (ql.length >= 5 && el.length >= 5 && withinOneEdit(ql, el))) return 'near match';
  }
  const shorter = q.length <= e.length ? q : e;
  const longer = q.length <= e.length ? e : q;
  if (shorter.length >= 6 && containsPhrase(longer, shorter)) return 'near match';
  if (entry.commonName && qt[qt.length - 1] === et[et.length - 1]) return 'ambiguous';
  return null;
}

// input: { prospect, otherSide, description }. entries: firm/conflicts.json "entries".
// Returns { status: 'clear' | 'hold' | 'not_provided', matches: [{ id, side, role, reason }] }.
function checkConflicts(input, entries) {
  const matches = [];
  const seen = {};
  const add = (entry, side, reason) => {
    const key = entry.id + '|' + side;
    if (seen[key]) return;
    seen[key] = true;
    matches.push({ id: entry.id, side, role: entry.role, reason });
  };
  const isClientRole = (e) => e.role === 'client' || e.role === 'former_client';

  const otherNames = splitNames(input.otherSide);
  for (const entry of entries) {
    if (!isClientRole(entry)) continue;
    for (const q of otherNames) {
      const reason = compareName(q, entry);
      if (reason) { add(entry, 'other_side', reason); break; }
    }
  }

  const prospect = normalizeName(input.prospect);
  if (prospect) {
    for (const entry of entries) {
      const reason = compareName(prospect, entry);
      if (reason) add(entry, 'prospect', reason);
    }
  }

  const description = normalizeName(input.description);
  if (description) {
    for (const entry of entries) {
      if (!isClientRole(entry)) continue;
      const full = normalizeName(entry.name);
      if (full.split(' ').length >= 2 && containsPhrase(description, full)) add(entry, 'description', 'named in description');
    }
  }

  const status = matches.length ? 'hold' : (otherNames.length ? 'clear' : 'not_provided');
  return { status, matches };
}

// ---- firm/lib/urgency.js ----
// Flag messages that look time-sensitive: court dates, served papers, deadlines, safety, arrest, lockout.
// data is firm/urgency.json. today is 'YYYY-MM-DD' in the firm's timezone.
// Rules this code follows (see firm/urgency.json "neverDo"):
//   - it only repeats a date as the sender wrote it; it never says what a legal deadline is,
//   - a flag is a request for a person to look, never advice.

const URGENCY_MONTHS = {
  january: 1, jan: 1, february: 2, feb: 2, march: 3, mar: 3, april: 4, apr: 4, may: 5, june: 6, jun: 6,
  july: 7, jul: 7, august: 8, aug: 8, september: 9, sept: 9, sep: 9, october: 10, oct: 10,
  november: 11, nov: 11, december: 12, dec: 12
};
const URGENCY_WEEKDAYS = { sunday: 0, monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6 };
const URGENCY_NEAR_CHARS = 90;

function isoToUtc(iso) {
  const p = iso.split('-').map(Number);
  return Date.UTC(p[0], p[1] - 1, p[2]);
}
function utcToIso(ms) {
  const d = new Date(ms);
  return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0');
}
function daysFromToday(iso, today) {
  return Math.round((isoToUtc(iso) - isoToUtc(today)) / 86400000);
}
function validParts(y, m, d) {
  if (m < 1 || m > 12 || d < 1 || d > 31) return false;
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}
// A date written without a year means the nearest one that is not much in the past.
function resolveYear(m, d, today) {
  const ty = Number(today.slice(0, 4));
  let y = ty;
  if (validParts(y, m, d) && daysFromToday(y + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0'), today) < -30) y = ty + 1;
  return y;
}
function makeDate(y, m, d, today, raw, index) {
  const year = y == null ? resolveYear(m, d, today) : (y < 100 ? 2000 + y : y);
  if (!validParts(year, m, d)) return null;
  const iso = year + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0');
  return { raw, iso, days: daysFromToday(iso, today), index };
}

// Dates written in the text: 2026-11-16, 11/16, 11/16/2026, Nov 16, November 16th 2026, 16 November,
// plus tomorrow, today, tonight, yesterday, 'in 3 days' and weekday names.
function extractDates(text, today, original) {
  const out = [];
  const orig = original || text;
  let work = text;
  const monthNames = Object.keys(URGENCY_MONTHS).join('|');
  const todayWd = new Date(isoToUtc(today)).getUTCDay();
  const take = (re, build0) => {
    // builders see m.raw: the sender's own wording of the date, with their capital letters
    const build = (m) => { m.raw = orig.substr(m.index, m[0].length); return build0(m); };
    re.lastIndex = 0;
    let m;
    const spans = [];
    while ((m = re.exec(work))) {
      const d = build(m);
      if (d) out.push(d);
      spans.push([m.index, m.index + m[0].length]);
      if (m[0].length === 0) re.lastIndex++;
    }
    spans.forEach((s) => { work = maskSpan(work, s[0], s[1]); });
  };
  take(/\b(\d{4})-(\d{2})-(\d{2})\b/g, (m) => makeDate(+m[1], +m[2], +m[3], today, m.raw, m.index));
  take(new RegExp('\\b(' + monthNames + ')\\.?\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s+(\\d{4}))?\\b', 'g'),
    (m) => makeDate(m[3] ? +m[3] : null, URGENCY_MONTHS[m[1]], +m[2], today, m.raw, m.index));
  take(new RegExp('\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+(?:of\\s+)?(' + monthNames + ')\\b\\.?(?:,?\\s+(\\d{4}))?', 'g'),
    (m) => makeDate(m[3] ? +m[3] : null, URGENCY_MONTHS[m[2]], +m[1], today, m.raw, m.index));
  take(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/g, (m) => makeDate(m[3] ? +m[3] : null, +m[1], +m[2], today, m.raw, m.index));
  const rel = (days) => (m) => ({ raw: m.raw, iso: utcToIso(isoToUtc(today) + days * 86400000), days, index: m.index });
  take(/\btomorrow\b/g, rel(1));
  take(/\b(?:today|tonight|this (?:morning|afternoon|evening))\b/g, rel(0));
  take(/\byesterday\b/g, rel(-1));
  take(/\b(?:in|within) (\d{1,2}) days?\b/g, (m) => rel(+m[1])(m));
  take(/\b(\d{1,2}) days? (?:left|to respond|to file|from now)\b/g, (m) => rel(+m[1])(m));
  // 'the 16th' with no month: the next time that day of the month comes round.
  take(/\bthe (\d{1,2})(?:st|nd|rd|th)\b/g, (m) => {
    const t = today.split('-').map(Number);
    let y = t[0];
    let mo = t[1];
    if (+m[1] < t[2]) { mo += 1; if (mo > 12) { mo = 1; y += 1; } }
    return makeDate(y, mo, +m[1], today, m.raw, m.index);
  });
  // A weekday means the next one coming. 'next Monday' is read the same way, because the other
  // reading (the Monday after) would make a hearing look further away than it may be.
  take(/\b(?:next )?(sunday|monday|tuesday|wednesday|thursday|friday|saturday)\b/g, (m) => {
    const days = ((URGENCY_WEEKDAYS[m[1]] - todayWd + 7) % 7) || 7;
    return rel(days)(m);
  });
  return out.sort((a, b) => a.index - b.index);
}

// input: { text, hearing } where hearing is the form answer: none | within7 | later | unsure.
// Returns { level: 'urgent' | 'check' | 'none', timeClass, flags, alsoShow }.
//   urgent = a person should look straight away; check = time-sensitive but nothing says it is within the window.
function detectUrgency(input, data, today) {
  // A lowercase copy with the same length as the original, so indexes line up and dates keep the sender's wording.
  const original = String((input && input.text) || '');
  const text = stripHarmlessPhrases(original.toLowerCase());
  const hearing = (input && input.hearing) || 'none';
  const threshold = data.dayThreshold;
  const dates = extractDates(text, today, original);
  const flags = [];

  for (const cat of data.categories) {
    const found = [];
    for (const phrase of cat.phrases) {
      const m = findPhrase(text, phrase);
      if (m) found.push({ phrase, index: m.index });
    }
    if (!found.length) continue;
    const flag = { id: cat.id, label: cat.label, why: cat.why, phrases: found.map((f) => f.phrase), level: 'urgent', reason: 'raised on sight', date: null, alsoShow: cat.alsoShow || null };
    if (cat.usesDateWindow) {
      let best = null;
      for (const f of found) {
        for (const d of dates) {
          const dist = Math.abs(d.index - f.index);
          if (dist > URGENCY_NEAR_CHARS) continue;
          if (!best || dist < best.dist || (dist === best.dist && d.days > best.d.days)) best = { dist, d };
        }
      }
      if (!best) {
        flag.level = 'check'; flag.reason = 'no date given';
      } else {
        flag.date = { raw: best.d.raw, iso: best.d.iso, days: best.d.days };
        if (best.d.days < 0) { flag.level = 'urgent'; flag.reason = 'date has passed (as written)'; }
        else if (best.d.days <= threshold) { flag.level = 'urgent'; flag.reason = 'date within ' + threshold + ' days (as written)'; }
        else { flag.level = 'check'; flag.reason = 'date later than ' + threshold + ' days (as written)'; }
      }
    }
    flags.push(flag);
  }

  if (hearing === 'within7') {
    flags.push({ id: 'self_reported', label: 'Sender says a hearing or deadline is within ' + threshold + ' days', why: 'Stated on the form.', phrases: [], level: 'urgent', reason: 'form answer', date: null, alsoShow: null });
  } else if (hearing === 'later') {
    flags.push({ id: 'self_reported_later', label: 'Sender says a hearing or deadline is later than ' + threshold + ' days', why: 'Stated on the form.', phrases: [], level: 'check', reason: 'form answer', date: null, alsoShow: null });
  } else if (hearing === 'unsure') {
    flags.push({ id: 'self_reported_unsure', label: 'Sender is not sure whether a hearing or deadline is close', why: 'Stated on the form.', phrases: [], level: 'check', reason: 'form answer', date: null, alsoShow: null });
  }

  const urgent = flags.some((f) => f.level === 'urgent');
  const level = urgent ? 'urgent' : (flags.length ? 'check' : 'none');
  let timeClass = 'none';
  if (urgent) timeClass = 'within7';
  else if (flags.some((f) => (f.date && f.date.days > threshold) || f.id === 'self_reported_later')) timeClass = 'later';
  else if (flags.length) timeClass = 'unsure';
  const alsoShow = Array.from(new Set(flags.map((f) => f.alsoShow).filter(Boolean)));
  return { level, timeClass, flags, alsoShow };
}

// ---- automations/intake/lib/intake.js ----
// Hollis & Marr lead intake: validate a website form, match it to a practice area, check conflicts,
// flag urgent wording, score it 0-100 and decide the next step. Pure functions. No model, no I/O.
// The visitor reply is a fixed template: it never gives legal advice, never states a legal deadline,
// never promises a response time and never says why a lead is on hold.

const INTAKE_OPTIONS = {
  location: ['harlow_point', 'nearby', 'elsewhere'],
  hearing: ['none', 'within7', 'later', 'unsure'],
  preferredContact: ['email', 'phone'],
  howHeard: ['', 'search', 'friend', 'attorney_referral', 'social', 'other']
};
const INTAKE_LIMITS = { description: { min: 20, max: 1500 }, name: { min: 2, max: 100 }, otherSide: { max: 200 }, earliestIncident: '1990-01-01' };
const INTAKE_POINTS = {
  area: { selected: 35, selected_unsupported: 20, inferred: 25, differs: 15, mixed: 15, unclear: 10, out_of_scope: 0 },
  location: { harlow_point: 15, nearby: 8, elsewhere: 0 },
  time: { within7: 20, later: 12, unsure: 6, none: 0 },
  descriptionBands: [[300, 12], [120, 8], [40, 4], [0, 0]],
  incidentDate: 4,
  otherSide: 4,
  email: 5,
  phone: 5
};
const INTAKE_TIERS = { hot: 75, warm: 50 };

function cleanString(v, max) {
  return String(v == null ? '' : v).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').replace(/[ \t]+/g, ' ').trim().slice(0, max == null ? 5000 : max + 1);
}

// body: what the form posted. data: { areas, ... }. today: 'YYYY-MM-DD'.
// Returns { ok: true, clean } or { ok: false, errors } or { ok: false, spam: true } for the honeypot.
function validateIntake(body, data, today) {
  const b = body || {};
  if (cleanString(b.website, 50)) return { ok: false, spam: true };
  const errors = {};
  const areaIds = data.areas.areas.map((a) => a.id).concat(['not_sure', 'other']);
  const clean = {
    name: cleanString(b.name, INTAKE_LIMITS.name.max),
    email: cleanString(b.email, 254).toLowerCase(),
    phone: cleanString(b.phone, 30),
    preferredContact: cleanString(b.preferredContact, 10) || 'email',
    area: cleanString(b.area, 20) || 'not_sure',
    description: cleanString(b.description, INTAKE_LIMITS.description.max),
    location: cleanString(b.location, 20),
    hearing: cleanString(b.hearing, 10) || 'none',
    incidentDate: cleanString(b.incidentDate, 10),
    otherSide: cleanString(b.otherSide, INTAKE_LIMITS.otherSide.max),
    howHeard: cleanString(b.howHeard, 20)
  };
  if (clean.name.length < INTAKE_LIMITS.name.min || clean.name.length > INTAKE_LIMITS.name.max || !/^[\p{L}\p{M}0-9 .,'’-]+$/u.test(clean.name)) errors.name = 'Please enter your name using letters, spaces, hyphens or apostrophes.';
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(clean.email)) errors.email = 'Please enter a valid email address.';
  if (clean.phone) {
    const digits = clean.phone.replace(/\D/g, '');
    if (digits.length < 7 || digits.length > 15 || /[^0-9+()\-. ]/.test(clean.phone)) errors.phone = 'Please enter a valid phone number, or leave it blank.';
  }
  if (INTAKE_OPTIONS.preferredContact.indexOf(clean.preferredContact) === -1) errors.preferredContact = 'Please choose email or phone.';
  else if (clean.preferredContact === 'phone' && !clean.phone) errors.phone = 'Please add a phone number if you prefer a call.';
  if (areaIds.indexOf(clean.area) === -1) errors.area = 'Please choose one of the options.';
  if (clean.description.length < INTAKE_LIMITS.description.min) errors.description = 'Please describe your situation in a few sentences.';
  else if (clean.description.length > INTAKE_LIMITS.description.max) errors.description = 'Please keep it under ' + INTAKE_LIMITS.description.max + ' characters.';
  if (INTAKE_OPTIONS.location.indexOf(clean.location) === -1) errors.location = 'Please tell us where you are.';
  if (INTAKE_OPTIONS.hearing.indexOf(clean.hearing) === -1) errors.hearing = 'Please choose one of the options.';
  if (INTAKE_OPTIONS.howHeard.indexOf(clean.howHeard) === -1) errors.howHeard = 'Please choose one of the options.';
  if (clean.otherSide.length > INTAKE_LIMITS.otherSide.max) errors.otherSide = 'Please keep it under ' + INTAKE_LIMITS.otherSide.max + ' characters.';
  if (clean.incidentDate) {
    const ok = /^\d{4}-\d{2}-\d{2}$/.test(clean.incidentDate) && !isNaN(Date.parse(clean.incidentDate + 'T00:00:00Z')) &&
      new Date(clean.incidentDate + 'T00:00:00Z').toISOString().slice(0, 10) === clean.incidentDate;
    if (!ok) errors.incidentDate = 'Please use a real date, or leave it blank.';
    else if (daysFromToday(clean.incidentDate, today) > 0) errors.incidentDate = 'The date cannot be in the future.';
    else if (clean.incidentDate < INTAKE_LIMITS.earliestIncident) errors.incidentDate = 'Please use a real date, or leave it blank.';
  }
  const consent = b.consent === true || b.consent === 'true' || b.consent === 'on' || b.consent === 'yes';
  if (!consent) errors.consent = 'Please confirm that you agree to be contacted and understand this is not legal advice.';
  return Object.keys(errors).length ? { ok: false, errors } : { ok: true, clean };
}

function descriptionPoints(len) {
  for (const band of INTAKE_POINTS.descriptionBands) if (len >= band[0]) return band[1];
  return 0;
}

// 0-100: area fit 35, location 15, time 20, detail 20, contactability 10.
function scoreIntake(clean, area, urgency, hearingClass) {
  const classes = ['none', 'unsure', 'later', 'within7'];
  const timeClass = classes.indexOf(hearingClass) > classes.indexOf(urgency.timeClass) ? hearingClass : urgency.timeClass;
  const parts = {
    area: INTAKE_POINTS.area[area.area === 'out_of_scope' ? 'out_of_scope' : area.basis] || 0,
    location: INTAKE_POINTS.location[clean.location] || 0,
    time: INTAKE_POINTS.time[timeClass] || 0,
    detail: descriptionPoints(clean.description.length) + (clean.incidentDate ? INTAKE_POINTS.incidentDate : 0) + (clean.otherSide ? INTAKE_POINTS.otherSide : 0),
    contact: INTAKE_POINTS.email + (clean.phone ? INTAKE_POINTS.phone : 0)
  };
  const total = parts.area + parts.location + parts.time + parts.detail + parts.contact;
  return { total, parts, timeClass };
}

// Tier and next step. Order matters and is part of the design (see README):
//   not_a_fit > refer_out > hold_conflict > attorney_now > ask_more > follow_up > book
function decideIntake(clean, area, urgency, conflict, score) {
  let tier = score.total >= INTAKE_TIERS.hot ? 'Hot' : (score.total >= INTAKE_TIERS.warm ? 'Warm' : 'Low');
  if (conflict.status === 'hold' && tier === 'Hot') tier = 'Warm';
  let nextStep;
  if (clean.location === 'elsewhere') { nextStep = 'not_a_fit'; tier = 'Not a fit'; }
  else if (area.area === 'out_of_scope') { nextStep = 'refer_out'; tier = 'Refer out'; }
  else if (conflict.status === 'hold') nextStep = 'hold_conflict';
  else if (urgency.level === 'urgent') nextStep = 'attorney_now';
  else if (area.area === 'unclear') nextStep = 'ask_more';
  else if (area.basis === 'mixed' || area.basis === 'differs' || tier === 'Low') nextStep = 'follow_up';
  else nextStep = 'book';
  let priority = 'low';
  if (urgency.level === 'urgent') priority = 'urgent';
  else if (tier === 'Hot' || urgency.level === 'check') priority = 'high';
  else if (tier === 'Warm') priority = 'normal';
  // The attorney on duty is not paged for matters the firm cannot take, unless safety wording is present.
  const cannotTake = nextStep === 'refer_out' || nextStep === 'not_a_fit';
  const safety = urgency.flags.some((f) => f.id === 'safety');
  return { tier, nextStep, priority, alert: (priority === 'urgent' || tier === 'Hot') && (!cannotTake || safety) };
}

function areaById(data, id) {
  return data.areas.areas.find((a) => a.id === id) || null;
}

// Fixed templates. firm: firm.json (name, phone, domain, officeHours, emails, language).
function visitorMessage(result, data) {
  const firm = data.firm;
  const first = (result.name || '').split(' ')[0] || 'there';
  const hours = 'Monday to Friday, ' + firm.officeHours.open.replace(/^0/, '') + '-' + firm.officeHours.close;
  const bookUrl = 'https://' + firm.domain + '/book';
  const area = areaById(data, result.areaFinal);
  const lines = [];
  // A held lead that is also urgent gets the 'flagged for a person' wording. It does not hint at the conflict.
  const step = result.nextStep === 'hold_conflict' && result.urgent ? 'attorney_now' : result.nextStep;
  let headline;
  if (step === 'book') {
    headline = 'Thanks, ' + first + '. The next step is to book a first consultation.';
    lines.push('Your message looks like a ' + area.name.toLowerCase() + ' matter, which the firm handles.');
    lines.push(area.consult.feeUsd === 0
      ? 'The first ' + area.consult.minutes + '-minute consultation is free.'
      : 'The first consultation is ' + area.consult.minutes + ' minutes and costs $' + area.consult.feeUsd + ', credited to the retainer if you hire the firm.');
    lines.push('You can book at any hour: ' + bookUrl);
  } else if (step === 'follow_up') {
    headline = 'Thanks, ' + first + '. A member of the team will read your message.';
    lines.push('Someone will reply to you by ' + (result.preferredContact === 'phone' ? 'phone' : 'email') + '. If you would like to move faster, you can book a first consultation at any hour: ' + bookUrl);
  } else if (step === 'ask_more') {
    headline = 'Thanks, ' + first + '. A member of the team will read your message.';
    lines.push('It was not clear from the message which kind of matter this is, so someone may reply with a question. You can also email ' + firm.emails.general + ' or call ' + firm.phone + ' during office hours (' + hours + ').');
  } else if (step === 'hold_conflict') {
    headline = 'Thanks, ' + first + '. A member of the team will review your message.';
    lines.push('Someone will contact you using the details you gave.');
  } else if (step === 'attorney_now') {
    headline = 'Thanks, ' + first + '. Your message has been flagged for a person at the firm.';
    lines.push('You mentioned a court date, legal papers or a deadline, so your message is marked for an attorney to look at as soon as possible. Court dates and deadlines are strict, so please also call the office on ' + firm.phone + ' during office hours (' + hours + '). This reply cannot tell you what any deadline is, and the firm cannot promise a response time.');
  } else if (step === 'refer_out') {
    const cat = result.outOfScope;
    headline = 'Thanks, ' + first + '. This looks like a matter the firm does not handle.';
    lines.push('From your message this appears to be ' + (cat ? cat.name.toLowerCase() : 'outside the areas the firm handles') + '. ' + (cat ? 'We suggest ' + cat.referral + '.' : data.areas.referralNote));
    lines.push('If a time limit may be running, please contact another lawyer quickly.');
  } else {
    headline = 'Thanks, ' + first + '. The firm cannot take this matter.';
    lines.push('Hollis & Marr helps people in Harlow Point and the surrounding area, and can only take matters in the courts where its attorneys are licensed. We suggest contacting your local bar association\'s lawyer referral service. If a time limit may be running, please contact another lawyer quickly.');
  }
  const show = result.alsoShow || [];
  if (show.indexOf('emergency') !== -1) lines.push(firm.language.emergency);
  if (show.indexOf('referral') !== -1 && step !== 'refer_out') {
    lines.push('Some of what you described, such as an arrest or a housing notice, is not something the firm handles. The firm does not recommend a specific outside lawyer; please contact your local bar association\'s lawyer referral service.');
  }
  lines.push(firm.language.aiDisclosure + ' ' + firm.language.notLegalAdvice);
  lines.push(firm.language.noConfidential);
  return { headline, text: [headline].concat(lines).join('\n\n') };
}

function leadSummary(r) {
  return {
    ref: r.ref, tier: r.tier, score: r.score, priority: r.priority, nextStep: r.nextStep, areaFinal: r.areaFinal,
    urgency: r.urgencyLevel, conflict: r.conflictStatus
  };
}

// data: { firm, areas (practice-areas.json), urgency (urgency.json), conflicts (conflicts.json entries array as .entries) }
// ctx: { today: 'YYYY-MM-DD', ref: 'HM-...' , now: ISO string }
function processIntake(body, data, ctx) {
  const v = validateIntake(body, data, ctx.today);
  if (v.spam) return { ok: true, spam: true };
  if (!v.ok) return { ok: false, errors: v.errors };
  const c = v.clean;
  const area = classifyArea({ selected: c.area, text: c.description }, data.areas);
  const urgency = detectUrgency({ text: c.description, hearing: c.hearing }, data.urgency, ctx.today);
  const conflict = checkConflicts({ prospect: c.name, otherSide: c.otherSide, description: c.description }, data.conflicts.entries);
  const score = scoreIntake(c, area, urgency, c.hearing);
  const decision = decideIntake(c, area, urgency, conflict, score);
  const areaRow = areaById(data, area.area);
  const alsoShow = urgency.alsoShow;
  const lead = {
    ref: ctx.ref,
    receivedAt: ctx.now || '',
    status: 'new',
    name: c.name,
    email: c.email,
    phone: c.phone,
    preferredContact: c.preferredContact,
    areaSelected: c.area,
    areaFinal: area.area,
    areaBasis: area.basis,
    areaNotes: [].concat(area.alsoMentions.length ? ['also mentions: ' + area.alsoMentions.join(', ')] : [], area.alsoOutOfScope.length ? ['also mentions (not handled): ' + area.alsoOutOfScope.join(', ')] : []).join('; '),
    location: c.location,
    hearing: c.hearing,
    incidentDate: c.incidentDate,
    otherSide: c.otherSide,
    howHeard: c.howHeard,
    description: c.description,
    score: score.total,
    scoreParts: JSON.stringify(score.parts),
    tier: decision.tier,
    priority: decision.priority,
    nextStep: decision.nextStep,
    urgencyLevel: urgency.level,
    urgencyFlags: urgency.flags.map((f) => f.label + (f.date ? ' [' + f.date.raw + ', ' + f.reason + ']' : ' [' + f.reason + ']')).join('; '),
    conflictStatus: conflict.status,
    conflictNote: conflict.matches.map((m) => m.id + ' ' + m.side + ': ' + m.reason).join('; '),
    suggestedAttorneys: areaRow ? areaRow.attorneys.join(',') : ''
  };
  const visitor = visitorMessage({
    name: c.name, preferredContact: c.preferredContact, nextStep: decision.nextStep, areaFinal: area.area, outOfScope: area.outOfScope, alsoShow, urgent: urgency.level === 'urgent'
  }, data);
  const alertLines = [
    'Ref: ' + lead.ref,
    'Priority: ' + decision.priority.toUpperCase() + '   Tier: ' + decision.tier + '   Score: ' + score.total + '/100',
    'Area: ' + c.area + ' selected, ' + area.area + ' final (' + area.basis + ')',
    'Next step: ' + decision.nextStep,
    'Time-sensitive: ' + (urgency.flags.length ? urgency.flags.map((f) => f.label + ' - ' + f.reason + (f.date ? ' ("' + f.date.raw + '")' : '')).join('; ') : 'nothing flagged'),
    'Conflict check: ' + conflict.status + (conflict.matches.length ? ' (' + lead.conflictNote + ')' : ''),
    'Contact preference: ' + c.preferredContact,
    '',
    'The message text and contact details are in the intake_leads table under this ref. They are not repeated in this email.',
    'This is a prompt for a person to look. It is not legal advice and it does not say what any deadline is.'
  ];
  const alert = {
    send: decision.alert,
    subject: '[H&M intake] ' + decision.priority.toUpperCase() + ' ' + lead.ref + ' - ' + (areaRow ? areaRow.name : area.area) + ' - ' + decision.nextStep,
    text: alertLines.join('\n')
  };
  return { ok: true, lead, visitor, alert, summary: leadSummary(lead) };
}

// ---- n8n glue: the only part written for n8n. Everything above is the tested library. ----
// TEST_NOW is a variable the parity test passes in. It does not exist in n8n, and a visitor cannot set it.
const NOW = (typeof TEST_NOW !== 'undefined' && TEST_NOW) ? new Date(TEST_NOW) : new Date();
const TODAY = new Intl.DateTimeFormat('en-CA', { timeZone: DATA.firm.timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(NOW);
const results = [];
for (const item of $input.all()) {
  const raw = item.json || {};
  const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
  const ref = 'HM-' + TODAY.replace(/-/g, '').slice(2) + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
  results.push({ json: processIntake(body, DATA, { today: TODAY, ref, now: NOW.toISOString() }) });
}
return results;
